    min-height: 0;
    padding: 0;
    margin: 0;
    border: none;
    background: transparent;
}

#workspaces.taskbar .taskbar-window {
    padding: 2px 4px;
    margin: 0 2px;
    border-radius: 5px;
}

#workspaces.taskbar .taskbar-window:hover {
    background: rgba(137, 180, 250, 0.3);
}
