     "custom/divider",
     "bluetooth#icon",
     "bluetooth",
     "custom/divider",
     "battery",
     "custom/battery-icon"
   ],

  "hyprland/workspaces": {
    "format": "{name}",
    "all-outputs": true,
    "ignore-hidden": false,
    "on-click": "activate",
    "tooltip": false,
  },

  "custom/taskbar-divider": {
    "exec": "/home/krubics/.config/waybar/scripts/workspace-tabs.sh",
    "return-type": "json",
    "restart-interval": 0,
