input.old_string:
/* Shared geometry for every sprite: 26px box + 2px padding + 4px margin = the
   38px bar height. background-size: contain fits the sprite inside the content
   box, so height lands on 26px only where min-width >= 26 * aspect ratio. */
#custom-clock-icon,
#network.icon,
#bluetooth.icon,
#custom-battery-icon {
    background-position: center;
    background-repeat: no-repeat;
    background-size: contain;
    background-origin: content-box;
    color: transparent; /* hides the placeholder space glyph */
    min-width: 26px;
    min-height: 26px;
    padding: 2px;
    margin: 4px 0;
}

#custom-clock-icon { background-image: url('/home/krubics/.config/waybar/assets/dialga.png'); }
#network.icon      { background-image: url('/home/krubics/.config/waybar/assets/wooper.png'); }
#bluetooth.icon    { background-image: url('/home/krubics/.config/waybar/assets/magneton.png'); }

/* The pikachu sprites are 677x200; 26 * 3.385 = 88, or contain letterboxes them short */
#custom-battery-icon { min-width: 88px; }

input.new_string:
/* Shared geometry for every sprite. The PNGs are alpha-trimmed (originals in
   assets/original/), so the sprite's ink fills its canvas and a 26px content
   box renders a 26px-tall pokemon. background-size: contain only reaches that
   height where min-width >= 26 * aspect ratio; 30px covers the widest of the
   square-ish icons (wooper, at 1.167:1). */
#custom-clock-icon,
#network.icon,
#bluetooth.icon,
#custom-battery-icon {
    background-position: center;
    background-repeat: no-repeat;
    background-size: contain;
    background-origin: content-box;
    color: transparent; /* hides the placeholder space glyph */
    min-width: 30px;
    min-height: 26px;
    padding: 2px;
    margin: 4px 0;
}

#custom-clock-icon { background-image: url('/home/krubics/.config/waybar/assets/dialga.png'); }
#network.icon      { background-image: url('/home/krubics/.config/waybar/assets/wooper.png'); }
#bluetooth.icon    { background-image: url('/home/krubics/.config/waybar/assets/magneton.png'); }

/* A 5-cell gauge, not one pikachu: 629x126, so 26 * 4.992 = 130px of width */
#custom-battery-icon { min-width: 130px; }

